UPDATE lessons SET title='Report Architect: Plan an Information Report',data=json_patch(data,'{"seed_key":"s2-eng-y3-w06-l2","title":"Report Architect: Plan an Information Report","stage":"Stage 2","learning_area":"English","year_level":3,"week":6,"lesson_number":2,"duration_minutes":60,"child_mission":"Investigate report architect: plan an information report, learn from complete examples and solve an original mission.","learning_intention":"We are learning to explain and use report architect: plan an information report accurately.","success_criteria":["I can explain the topic using an accurate example.","I can follow a worked example and explain the method.","I can practise with feedback before working independently.","I can complete the original challenge.","I can identify and explain one useful correction."],"materials":["Original passages and examples included","Optional paper and pencil or ordinary counters"],"outcome_codes":[],"review_status":"unreviewed","pass":1,"pass_mark":0.9,"coming_soon":null,"source_note":null,"explicit_teaching":null,"resources":null,"sort_activity":null,"word_challenges":null,"suspense_builder":null,"planner_fields":null,"planner_title":null,"planner_intro":null,"spelling":null,"spelling_focus":null,"hoard_words":null,"follow_up_challenges":null,"steps":null,"visual_plan":null,"interactive_activities":[{"type":"flip_cards","title":"Four topic concepts","cards":[{"front":"Choose a factual topic and reader","back":"An information report explains a topic with organised facts, not an invented adventure. A clear reader and purpose tell us what belongs."},{"front":"Group related information","back":"A report usually starts with an introduction naming the topic, then uses subheadings to group different aspects."},{"front":"Turn notes into factual points","back":"Notes are short reminders, not full paragraphs. Separate reliable observations from unverified claims."},{"front":"Build a paragraph plan and check","back":"Place one main idea and supporting detail beneath each heading. Check the plan covers the topic without repetition."}]}],"printable_resource":{"title":"Report Architect: Plan an Information Report","instructions":"Read the information, complete guided practice and submit your own independent response.","passage":"A class needs a factual report explaining how frogs grow. The reader is another Year 3 learner.","prompts":["What information matters?","Which method applies?","What is my independent result?","How can I verify it?"]},"reflection_prompts":null,"reflection_prompt":null,"teach_steps":[{"icon":"🔎","title":"Choose a factual topic and reader","explain":"**Teach:** An information report explains a topic with organised facts, not an invented adventure. A clear reader and purpose tell us what belongs.\n\n**Look at the original information:** A class needs a factual report explaining how frogs grow. The reader is another Year 3 learner.\n\n**Notice:** Which exact part of the information illustrates this principle?","example":"**WATCH MY THINKING:** My purpose is to explain frog growth. I list what a reader needs: eggs, tadpoles, changes and adult frogs. I do not invent a talking frog.\n\n**TRY WITH SUPPORT:** **Plan a report about butterflies.** Select the reader (younger children), purpose (explain life stages), and headings: Introduction, Egg and Caterpillar, Chrysalis, Adult Butterfly. Put these facts under the best heading: caterpillars hatch from eggs; a chrysalis is part of transformation; adult butterflies have wings. **Feedback:** Egg and Caterpillar → hatching; Chrysalis → transformation; Adult Butterfly → wings. A story about a butterfly''s birthday would not be a factual report.\n\n**CHECK:** Explain a relevant correction, then compare your answer with the model.","notice":"An information report explains a topic with organised facts, not an invented adventure. A clear reader and purpose tell us what belongs.","check":{"question":"What is an information report for?","options":["To organise factual information","To invent a villain","To write only dialogue","To hide all facts"],"correct_index":0,"explanation":"To organise factual information. My purpose is to explain frog growth. I list what a reader needs: eggs, tadpoles, changes and adult frogs. I do not invent a talking frog."},"visual_before":[{"episode":{"title":"A clue about Report Architect: Plan an Information Report","transcript":"Pip: My frog report starts ''Once upon a time a frog drove a car.''\nJuno: That''s a story, not a factual report. Start by naming your topic and reader.\nPip: Then I group facts under headings such as eggs, tadpoles and adults.\nJuno: Exactly. Pause and choose a heading for facts about growing legs.","scenes":[{"bg":"room","lines":[{"who":"pip","text":"My frog report starts ''Once upon a time a frog drove a car.''"},{"who":"juno","text":"That''s a story, not a factual report. Start by naming your topic and reader."},{"who":"pip","text":"Then I group facts under headings such as eggs, tadpoles and adults."},{"who":"juno","text":"Exactly. Pause and choose a heading for facts about growing legs.","pause_after":true}]}]}}]},{"icon":"🧠","title":"Group related information","explain":"**Teach:** A report usually starts with an introduction naming the topic, then uses subheadings to group different aspects.\n\n**Look at the original information:** A class needs a factual report explaining how frogs grow. The reader is another Year 3 learner.\n\n**Notice:** Which exact part of the information illustrates this principle?","example":"**WATCH MY THINKING:** My plan uses Introduction: Frogs; From Eggs to Tadpoles; Changes as They Grow; Adult Frogs. Each heading has its own job.\n\n**TRY WITH SUPPORT:** **Plan a report about butterflies.** Select the reader (younger children), purpose (explain life stages), and headings: Introduction, Egg and Caterpillar, Chrysalis, Adult Butterfly. Put these facts under the best heading: caterpillars hatch from eggs; a chrysalis is part of transformation; adult butterflies have wings. **Feedback:** Egg and Caterpillar → hatching; Chrysalis → transformation; Adult Butterfly → wings. A story about a butterfly''s birthday would not be a factual report.\n\n**CHECK:** Explain a relevant correction, then compare your answer with the model.","notice":"A report usually starts with an introduction naming the topic, then uses subheadings to group different aspects.","check":{"question":"Which heading suits frog eggs?","options":["Adult Frog Calls","Eggs and Tadpoles","Publishing Credits","The End"],"correct_index":1,"explanation":"Eggs and Tadpoles. My plan uses Introduction: Frogs; From Eggs to Tadpoles; Changes as They Grow; Adult Frogs. Each heading has its own job."}},{"icon":"✏️","title":"Turn notes into factual points","explain":"**Teach:** Notes are short reminders, not full paragraphs. Separate reliable observations from unverified claims.\n\n**Look at the original information:** A class needs a factual report explaining how frogs grow. The reader is another Year 3 learner.\n\n**Notice:** Which exact part of the information illustrates this principle?","example":"**WATCH MY THINKING:** Under From Eggs to Tadpoles I note: ''eggs in jelly-like clusters; young hatch as tadpoles''. I avoid ''all frogs live in ponds'' because species differ.\n\n**TRY WITH SUPPORT:** **Plan a report about butterflies.** Select the reader (younger children), purpose (explain life stages), and headings: Introduction, Egg and Caterpillar, Chrysalis, Adult Butterfly. Put these facts under the best heading: caterpillars hatch from eggs; a chrysalis is part of transformation; adult butterflies have wings. **Feedback:** Egg and Caterpillar → hatching; Chrysalis → transformation; Adult Butterfly → wings. A story about a butterfly''s birthday would not be a factual report.\n\n**CHECK:** Explain a relevant correction, then compare your answer with the model.","notice":"Notes are short reminders, not full paragraphs. Separate reliable observations from unverified claims.","check":{"question":"Which note belongs under Adult Butterflies?","options":["The adult has wings","Eggs are in clusters","A chrysalis forms","A caterpillar eats"],"correct_index":0,"explanation":"The adult has wings. Under From Eggs to Tadpoles I note: ''eggs in jelly-like clusters; young hatch as tadpoles''. I avoid ''all frogs live in ponds'' because species differ."}},{"icon":"✅","title":"Build a paragraph plan and check","explain":"**Teach:** Place one main idea and supporting detail beneath each heading. Check the plan covers the topic without repetition.\n\n**Look at the original information:** A class needs a factual report explaining how frogs grow. The reader is another Year 3 learner.\n\n**Notice:** Which exact part of the information illustrates this principle?","example":"**WATCH MY THINKING:** My tadpole section will explain gills and swimming; the next section describes legs developing. I check the stages follow a sensible order.\n\n**TRY WITH SUPPORT:** **Plan a report about butterflies.** Select the reader (younger children), purpose (explain life stages), and headings: Introduction, Egg and Caterpillar, Chrysalis, Adult Butterfly. Put these facts under the best heading: caterpillars hatch from eggs; a chrysalis is part of transformation; adult butterflies have wings. **Feedback:** Egg and Caterpillar → hatching; Chrysalis → transformation; Adult Butterfly → wings. A story about a butterfly''s birthday would not be a factual report.\n\n**CHECK:** Explain a relevant correction, then compare your answer with the model.","notice":"Place one main idea and supporting detail beneath each heading. Check the plan covers the topic without repetition.","check":{"question":"Which is a useful report introduction?","options":["Frogs are amphibians that change as they grow.","Once a frog rode a bicycle.","Suddenly the pond exploded!","I am the brave frog king."],"correct_index":0,"explanation":"Frogs are amphibians that change as they grow.. My tadpole section will explain gills and swimming; the next section describes legs developing. I check the stages follow a sensible order."}}],"worked_example":"## Teacher model\n\nA class needs a factual report explaining how frogs grow. The reader is another Year 3 learner.\n\n**1. Choose a factual topic and reader:** My purpose is to explain frog growth. I list what a reader needs: eggs, tadpoles, changes and adult frogs. I do not invent a talking frog.\n\n**2. Group related information:** My plan uses Introduction: Frogs; From Eggs to Tadpoles; Changes as They Grow; Adult Frogs. Each heading has its own job.\n\n**3. Turn notes into factual points:** Under From Eggs to Tadpoles I note: ''eggs in jelly-like clusters; young hatch as tadpoles''. I avoid ''all frogs live in ponds'' because species differ.\n\n**4. Build a paragraph plan and check:** My tadpole section will explain gills and swimming; the next section describes legs developing. I check the stages follow a sensible order.\n\n**Explain:** What detail matters most in the model?","worked_visuals":[{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 580 180\"><rect width=\"580\" height=\"180\" rx=\"10\" fill=\"#f3f8f5\"/><text x=\"16\" y=\"29\" font-family=\"Arial\" font-size=\"18\" fill=\"#173d2b\">Plan a factual report</text><rect x=\"10\" y=\"58\" width=\"132\" height=\"96\" rx=\"9\" fill=\"#dbeee1\"/><text x=\"20\" y=\"109\" font-family=\"Arial\" font-size=\"15\" fill=\"#244132\">TOPIC</text><rect x=\"154\" y=\"58\" width=\"132\" height=\"96\" rx=\"9\" fill=\"#e3e9f9\"/><text x=\"164\" y=\"109\" font-family=\"Arial\" font-size=\"15\" fill=\"#244132\">SECTIONS</text><rect x=\"298\" y=\"58\" width=\"132\" height=\"96\" rx=\"9\" fill=\"#dbeee1\"/><text x=\"308\" y=\"109\" font-family=\"Arial\" font-size=\"15\" fill=\"#244132\">NOTES</text><rect x=\"442\" y=\"58\" width=\"132\" height=\"96\" rx=\"9\" fill=\"#e3e9f9\"/><text x=\"452\" y=\"109\" font-family=\"Arial\" font-size=\"15\" fill=\"#244132\">CHECK</text></svg>","alt":"Four linked steps for Report Architect: Plan an Information Report: TOPIC, SECTIONS, NOTES, CHECK.","caption":"Use the steps to organise and check your answer."}],"guided_practice":"**Plan a report about butterflies.** Select the reader (younger children), purpose (explain life stages), and headings: Introduction, Egg and Caterpillar, Chrysalis, Adult Butterfly. Put these facts under the best heading: caterpillars hatch from eggs; a chrysalis is part of transformation; adult butterflies have wings. **Feedback:** Egg and Caterpillar → hatching; Chrysalis → transformation; Adult Butterfly → wings. A story about a butterfly''s birthday would not be a factual report.","independent_task":"**Create a report plan titled Garden Earthworms.** Write a one-sentence purpose and intended reader. Plan an introduction and three suitable factual section headings: body and movement, habitat and food, and how earthworms affect soil. Put at least two accurate notes under each heading. Mark one claim to verify rather than present as certain. Finish with one sentence explaining how the headings help your reader.","response_prompt":"Complete the original report architect: plan an information report task, including evidence or working and one correction.","quiz":[{"type":"multiple_choice","question":"What is an information report for?","options":["To organise factual information","To invent a villain","To write only dialogue","To hide all facts"],"correct_index":0,"explanation":"To organise factual information. Compare this with the relevant taught example."},{"type":"multiple_choice","question":"Which heading suits frog eggs?","options":["Adult Frog Calls","Eggs and Tadpoles","Publishing Credits","The End"],"correct_index":1,"explanation":"Eggs and Tadpoles. Compare this with the relevant taught example."},{"type":"multiple_choice","question":"Which note belongs under Adult Butterflies?","options":["The adult has wings","Eggs are in clusters","A chrysalis forms","A caterpillar eats"],"correct_index":0,"explanation":"The adult has wings. Compare this with the relevant taught example."},{"type":"multiple_choice","question":"Which is a useful report introduction?","options":["Frogs are amphibians that change as they grow.","Once a frog rode a bicycle.","Suddenly the pond exploded!","I am the brave frog king."],"correct_index":0,"explanation":"Frogs are amphibians that change as they grow.. Compare this with the relevant taught example."},{"type":"multiple_choice","question":"Why group notes beneath headings?","options":["So related facts stay together","To make facts disappear","To avoid a topic","To replace all paragraphs"],"correct_index":0,"explanation":"So related facts stay together. Compare this with the relevant taught example."},{"type":"multiple_choice","question":"Which is the clearest note rather than a full paragraph?","options":["Eggs hatch into tadpoles","Here is my twelve-sentence story","Once upon a time","All my friends agree"],"correct_index":0,"explanation":"Eggs hatch into tadpoles. Compare this with the relevant taught example."},{"type":"multiple_choice","question":"Which earthworm heading suits movement?","options":["Body and Movement","Book Reviews","Competition Results","Frog Eggs"],"correct_index":0,"explanation":"Body and Movement. Compare this with the relevant taught example."},{"type":"multiple_choice","question":"What should happen to an uncertain claim?","options":["Check it using a reliable source","Present it as proven","Repeat it louder","Turn it into a quotation"],"correct_index":0,"explanation":"Check it using a reliable source. Compare this with the relevant taught example."},{"type":"short_answer","question":"Complete the independent report architect: plan an information report challenge.","sample_answer":"Purpose: explain earthworms to younger readers. Intro: Earthworms are animals that live in many soil habitats. Body and Movement: segmented bodies; move by contracting muscles. Habitat and Food: need moist conditions; feed on decaying organic material. Soil: burrows can change soil structure; waste contributes nutrients.","marking_guide":"Require the specific correct example, steps and reasoning.","explanation":"The answer must show the taught evidence or method."},{"type":"short_answer","question":"Explain a topic-specific checking method, misconception or improvement.","sample_answer":"I grouped body, habitat and soil effects separately so a reader can find each topic. I would verify any precise claim about how much soil a worm processes instead of inventing a number.","marking_guide":"Require the specific correct example, steps and reasoning.","explanation":"The answer must show the taught evidence or method."}],"parent_notes":"Parent: Check the actual independent response, ask for an explanation and support reading without giving away answers.\n\nParent: **First written model:** Purpose: explain earthworms to younger readers. Intro: Earthworms are animals that live in many soil habitats. Body and Movement: segmented bodies; move by contracting muscles. Habitat and Food: need moist conditions; feed on decaying organic material. Soil: burrows can change soil structure; waste contributes nutrients.\n\nParent: **Second written model:** I grouped body, habitat and soil effects separately so a reader can find each topic. I would verify any precise claim about how much soil a worm processes instead of inventing a number.\n\nParent: Review both written answers and the child''s evidence. The current 90% pass mark requires 8/8 scored MCQs. NESA codes remain unverified.","evidence_instructions":"Keep your report architect: plan an information report guided notes, independent task, correction and written responses.","offline_alternative":"Read or print the original text and work through the questions on paper; save work or parent observations.","extension":"Create an original harder report architect: plan an information report challenge and explain how you checked it.","stage_hints":{"accept":["Read the Report Architect: Plan an Information Report instruction and identify what you need to explain.","Return to the original text or numbers and locate a specific clue connected to report architect: plan an information report.","Use the clue or a calculation to justify your own answer, then check and correct a detail."],"teach0":["Read the Choose a factual topic and reader instruction and identify what you need to explain.","Return to the original text or numbers and locate a specific clue connected to choose a factual topic and reader.","Use the clue or a calculation to justify your own answer, then check and correct a detail."],"teach1":["Read the Group related information instruction and identify what you need to explain.","Return to the original text or numbers and locate a specific clue connected to group related information.","Use the clue or a calculation to justify your own answer, then check and correct a detail."],"teach2":["Read the Turn notes into factual points instruction and identify what you need to explain.","Return to the original text or numbers and locate a specific clue connected to turn notes into factual points.","Use the clue or a calculation to justify your own answer, then check and correct a detail."],"teach3":["Read the Build a paragraph plan and check instruction and identify what you need to explain.","Return to the original text or numbers and locate a specific clue connected to build a paragraph plan and check.","Use the clue or a calculation to justify your own answer, then check and correct a detail."],"learn":["Read the Report Architect: Plan an Information Report instruction and identify what you need to explain.","Return to the original text or numbers and locate a specific clue connected to report architect: plan an information report.","Use the clue or a calculation to justify your own answer, then check and correct a detail."],"guided":["Read the Report Architect: Plan an Information Report instruction and identify what you need to explain.","Return to the original text or numbers and locate a specific clue connected to report architect: plan an information report.","Use the clue or a calculation to justify your own answer, then check and correct a detail."],"write":["Read the Report Architect: Plan an Information Report instruction and identify what you need to explain.","Return to the original text or numbers and locate a specific clue connected to report architect: plan an information report.","Use the clue or a calculation to justify your own answer, then check and correct a detail."],"quiz":["Read the Report Architect: Plan an Information Report instruction and identify what you need to explain.","Return to the original text or numbers and locate a specific clue connected to report architect: plan an information report.","Use the clue or a calculation to justify your own answer, then check and correct a detail."],"submit":["Read the Report Architect: Plan an Information Report instruction and identify what you need to explain.","Return to the original text or numbers and locate a specific clue connected to report architect: plan an information report.","Use the clue or a calculation to justify your own answer, then check and correct a detail."]}}'),updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE seed_key='s2-eng-y3-w06-l2';

