UPDATE lessons SET title='Word Scientist: Understand Technical Vocabulary',data=json_patch(data,'{"seed_key":"s2-eng-y3-w06-l3","title":"Word Scientist: Understand Technical Vocabulary","stage":"Stage 2","learning_area":"English","year_level":3,"week":6,"lesson_number":3,"duration_minutes":60,"child_mission":"Investigate word scientist: understand technical vocabulary, learn from complete examples and solve an original mission.","learning_intention":"We are learning to explain and use word scientist: understand technical vocabulary accurately.","success_criteria":["I can explain the topic using an accurate example.","I can follow a worked example and explain the method.","I can practise with feedback before working independently.","I can complete the original challenge.","I can identify and explain one useful correction."],"materials":["Original passages and examples included","Optional paper and pencil or ordinary counters"],"outcome_codes":[],"review_status":"unreviewed","pass":1,"pass_mark":0.9,"coming_soon":null,"source_note":null,"explicit_teaching":null,"resources":null,"sort_activity":null,"word_challenges":null,"suspense_builder":null,"planner_fields":null,"planner_title":null,"planner_intro":null,"spelling":null,"spelling_focus":null,"hoard_words":null,"follow_up_challenges":null,"steps":null,"visual_plan":null,"interactive_activities":[{"type":"flip_cards","title":"Four topic concepts","cards":[{"front":"Recognise a technical term","back":"A technical word has a precise meaning in a subject. Its everyday use may be different or unfamiliar."},{"front":"Use context and word parts","back":"Read surrounding sentences for a definition, example or contrast. A prefix or familiar root can sometimes help, but check the meaning."},{"front":"Explain the word accurately","back":"A clear explanation uses everyday language without losing the essential science. Include an example when it helps."},{"front":"Apply and check in a new sentence","back":"Use a technical term where it fits, and compare it with a similar term so the reader can see the difference."}]}],"printable_resource":{"title":"Word Scientist: Understand Technical Vocabulary","instructions":"Read the information, complete guided practice and submit your own independent response.","passage":"A short nonfiction paragraph says: ''Evaporation happens when liquid water changes into water vapour. Condensation happens when vapour cools into liquid droplets.''","prompts":["What information matters?","Which method applies?","What is my independent result?","How can I verify it?"]},"reflection_prompts":null,"reflection_prompt":null,"teach_steps":[{"icon":"🔎","title":"Recognise a technical term","explain":"**Teach:** A technical word has a precise meaning in a subject. Its everyday use may be different or unfamiliar.\n\n**Look at the original information:** A short nonfiction paragraph says: ''Evaporation happens when liquid water changes into water vapour. Condensation happens when vapour cools into liquid droplets.''\n\n**Notice:** Which exact part of the information illustrates this principle?","example":"**WATCH MY THINKING:** Evaporation is not just ''water vanishes''. It names a change from liquid to gas. I find it near the explanation of water vapour.\n\n**TRY WITH SUPPORT:** **Mini-text:** ''A habitat is the place where an organism lives. Adaptations are features or behaviours that help it survive in its environment. A predator hunts other animals for food.'' Match: habitat→living place; adaptation→useful feature or behaviour; predator→hunter. Then write a sentence using one term accurately. **Feedback:** ''A rock pool can be a habitat for small sea animals'' uses habitat correctly. A habitat is not a type of animal.\n\n**CHECK:** Explain a relevant correction, then compare your answer with the model.","notice":"A technical word has a precise meaning in a subject. Its everyday use may be different or unfamiliar.","check":{"question":"Evaporation means?","options":["Liquid changing to gas","Gas changing to liquid","Ice forming rock","Water disappearing into nothing"],"correct_index":0,"explanation":"Liquid changing to gas. Evaporation is not just ''water vanishes''. It names a change from liquid to gas. I find it near the explanation of water vapour."},"visual_before":[{"episode":{"title":"A clue about Word Scientist: Understand Technical Vocabulary","transcript":"Pip: The puddle evaporated. Does that mean its water became nothing?\nJuno: No. The liquid became water vapour, a gas.\nPip: And condensation changes vapour back into liquid droplets.\nJuno: Good. Pause and describe what might happen on the outside of a cold glass.","scenes":[{"bg":"room","lines":[{"who":"pip","text":"The puddle evaporated. Does that mean its water became nothing?"},{"who":"juno","text":"No. The liquid became water vapour, a gas."},{"who":"pip","text":"And condensation changes vapour back into liquid droplets."},{"who":"juno","text":"Good. Pause and describe what might happen on the outside of a cold glass.","pause_after":true}]}]}}]},{"icon":"🧠","title":"Use context and word parts","explain":"**Teach:** Read surrounding sentences for a definition, example or contrast. A prefix or familiar root can sometimes help, but check the meaning.\n\n**Look at the original information:** A short nonfiction paragraph says: ''Evaporation happens when liquid water changes into water vapour. Condensation happens when vapour cools into liquid droplets.''\n\n**Notice:** Which exact part of the information illustrates this principle?","example":"**WATCH MY THINKING:** The words ''when liquid water changes into water vapour'' define evaporation. The later sentence contrasts condensation, so I keep the two processes distinct.\n\n**TRY WITH SUPPORT:** **Mini-text:** ''A habitat is the place where an organism lives. Adaptations are features or behaviours that help it survive in its environment. A predator hunts other animals for food.'' Match: habitat→living place; adaptation→useful feature or behaviour; predator→hunter. Then write a sentence using one term accurately. **Feedback:** ''A rock pool can be a habitat for small sea animals'' uses habitat correctly. A habitat is not a type of animal.\n\n**CHECK:** Explain a relevant correction, then compare your answer with the model.","notice":"Read surrounding sentences for a definition, example or contrast. A prefix or familiar root can sometimes help, but check the meaning.","check":{"question":"Condensation means?","options":["Rain becoming soil","Gas changing to liquid","Water turning into sand","Sunlight becoming water"],"correct_index":1,"explanation":"Gas changing to liquid. The words ''when liquid water changes into water vapour'' define evaporation. The later sentence contrasts condensation, so I keep the two processes distinct."}},{"icon":"✏️","title":"Explain the word accurately","explain":"**Teach:** A clear explanation uses everyday language without losing the essential science. Include an example when it helps.\n\n**Look at the original information:** A short nonfiction paragraph says: ''Evaporation happens when liquid water changes into water vapour. Condensation happens when vapour cools into liquid droplets.''\n\n**Notice:** Which exact part of the information illustrates this principle?","example":"**WATCH MY THINKING:** I say ''Evaporation happens when a puddle''s liquid water becomes invisible water vapour.'' I avoid saying it turns into nothing.\n\n**TRY WITH SUPPORT:** **Mini-text:** ''A habitat is the place where an organism lives. Adaptations are features or behaviours that help it survive in its environment. A predator hunts other animals for food.'' Match: habitat→living place; adaptation→useful feature or behaviour; predator→hunter. Then write a sentence using one term accurately. **Feedback:** ''A rock pool can be a habitat for small sea animals'' uses habitat correctly. A habitat is not a type of animal.\n\n**CHECK:** Explain a relevant correction, then compare your answer with the model.","notice":"A clear explanation uses everyday language without losing the essential science. Include an example when it helps.","check":{"question":"Which is an example of condensation?","options":["Droplets appearing on a cool glass","A puddle drying","A book opening","A leaf growing"],"correct_index":0,"explanation":"Droplets appearing on a cool glass. I say ''Evaporation happens when a puddle''s liquid water becomes invisible water vapour.'' I avoid saying it turns into nothing."}},{"icon":"✅","title":"Apply and check in a new sentence","explain":"**Teach:** Use a technical term where it fits, and compare it with a similar term so the reader can see the difference.\n\n**Look at the original information:** A short nonfiction paragraph says: ''Evaporation happens when liquid water changes into water vapour. Condensation happens when vapour cools into liquid droplets.''\n\n**Notice:** Which exact part of the information illustrates this principle?","example":"**WATCH MY THINKING:** ''Water droplets formed on the cold cup through condensation'' uses the word correctly. Calling the droplets evaporation would confuse opposite changes.\n\n**TRY WITH SUPPORT:** **Mini-text:** ''A habitat is the place where an organism lives. Adaptations are features or behaviours that help it survive in its environment. A predator hunts other animals for food.'' Match: habitat→living place; adaptation→useful feature or behaviour; predator→hunter. Then write a sentence using one term accurately. **Feedback:** ''A rock pool can be a habitat for small sea animals'' uses habitat correctly. A habitat is not a type of animal.\n\n**CHECK:** Explain a relevant correction, then compare your answer with the model.","notice":"Use a technical term where it fits, and compare it with a similar term so the reader can see the difference.","check":{"question":"What does habitat mean?","options":["An animal''s living place","A dangerous weather event","A place to buy clothes","A part of a sentence"],"correct_index":0,"explanation":"An animal''s living place. ''Water droplets formed on the cold cup through condensation'' uses the word correctly. Calling the droplets evaporation would confuse opposite changes."}}],"worked_example":"## Teacher model\n\nA short nonfiction paragraph says: ''Evaporation happens when liquid water changes into water vapour. Condensation happens when vapour cools into liquid droplets.''\n\n**1. Recognise a technical term:** Evaporation is not just ''water vanishes''. It names a change from liquid to gas. I find it near the explanation of water vapour.\n\n**2. Use context and word parts:** The words ''when liquid water changes into water vapour'' define evaporation. The later sentence contrasts condensation, so I keep the two processes distinct.\n\n**3. Explain the word accurately:** I say ''Evaporation happens when a puddle''s liquid water becomes invisible water vapour.'' I avoid saying it turns into nothing.\n\n**4. Apply and check in a new sentence:** ''Water droplets formed on the cold cup through condensation'' uses the word correctly. Calling the droplets evaporation would confuse opposite changes.\n\n**Explain:** What detail matters most in the model?","worked_visuals":[{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 580 180\"><rect width=\"580\" height=\"180\" rx=\"10\" fill=\"#f3f8f5\"/><text x=\"16\" y=\"29\" font-family=\"Arial\" font-size=\"18\" fill=\"#173d2b\">Understand technical words</text><rect x=\"10\" y=\"58\" width=\"132\" height=\"96\" rx=\"9\" fill=\"#dbeee1\"/><text x=\"20\" y=\"109\" font-family=\"Arial\" font-size=\"15\" fill=\"#244132\">TERM</text><rect x=\"154\" y=\"58\" width=\"132\" height=\"96\" rx=\"9\" fill=\"#e3e9f9\"/><text x=\"164\" y=\"109\" font-family=\"Arial\" font-size=\"15\" fill=\"#244132\">CONTEXT</text><rect x=\"298\" y=\"58\" width=\"132\" height=\"96\" rx=\"9\" fill=\"#dbeee1\"/><text x=\"308\" y=\"109\" font-family=\"Arial\" font-size=\"15\" fill=\"#244132\">MEANING</text><rect x=\"442\" y=\"58\" width=\"132\" height=\"96\" rx=\"9\" fill=\"#e3e9f9\"/><text x=\"452\" y=\"109\" font-family=\"Arial\" font-size=\"15\" fill=\"#244132\">USE</text></svg>","alt":"Four linked steps for Word Scientist: Understand Technical Vocabulary: TERM, CONTEXT, MEANING, USE.","caption":"Use the steps to organise and check your answer."}],"guided_practice":"**Mini-text:** ''A habitat is the place where an organism lives. Adaptations are features or behaviours that help it survive in its environment. A predator hunts other animals for food.'' Match: habitat→living place; adaptation→useful feature or behaviour; predator→hunter. Then write a sentence using one term accurately. **Feedback:** ''A rock pool can be a habitat for small sea animals'' uses habitat correctly. A habitat is not a type of animal.","independent_task":"**Make a mini-glossary of six terms:** evaporation, condensation, habitat, adaptation, predator and pollination. Give each a child-friendly, accurate definition and one original sentence that uses it. Then explain the difference between evaporation and condensation, and write one example of a word you clarified from context rather than guessing.","response_prompt":"Complete the original word scientist: understand technical vocabulary task, including evidence or working and one correction.","quiz":[{"type":"multiple_choice","question":"Evaporation means?","options":["Liquid changing to gas","Gas changing to liquid","Ice forming rock","Water disappearing into nothing"],"correct_index":0,"explanation":"Liquid changing to gas. Compare this with the relevant taught example."},{"type":"multiple_choice","question":"Condensation means?","options":["Rain becoming soil","Gas changing to liquid","Water turning into sand","Sunlight becoming water"],"correct_index":1,"explanation":"Gas changing to liquid. Compare this with the relevant taught example."},{"type":"multiple_choice","question":"Which is an example of condensation?","options":["Droplets appearing on a cool glass","A puddle drying","A book opening","A leaf growing"],"correct_index":0,"explanation":"Droplets appearing on a cool glass. Compare this with the relevant taught example."},{"type":"multiple_choice","question":"What does habitat mean?","options":["An animal''s living place","A dangerous weather event","A place to buy clothes","A part of a sentence"],"correct_index":0,"explanation":"An animal''s living place. Compare this with the relevant taught example."},{"type":"multiple_choice","question":"What can an adaptation be?","options":["A feature helping survival","Always a colour only","A map legend","A made-up creature"],"correct_index":0,"explanation":"A feature helping survival. Compare this with the relevant taught example."},{"type":"multiple_choice","question":"Which animal is acting as a predator?","options":["An owl hunting a mouse","A plant absorbing sunlight","A snail hiding","A tree making a seed"],"correct_index":0,"explanation":"An owl hunting a mouse. Compare this with the relevant taught example."},{"type":"multiple_choice","question":"What is pollination?","options":["Transfer of pollen between flowers","Water changing to vapour","Soil turning into rock","A plant walking"],"correct_index":0,"explanation":"Transfer of pollen between flowers. Compare this with the relevant taught example."},{"type":"multiple_choice","question":"How should you handle an unfamiliar scientific word?","options":["Look for context and check a definition","Guess and never check","Skip every sentence","Change its spelling"],"correct_index":0,"explanation":"Look for context and check a definition. Compare this with the relevant taught example."},{"type":"short_answer","question":"Complete the independent word scientist: understand technical vocabulary challenge.","sample_answer":"Evaporation is liquid changing into vapour; condensation is vapour changing into liquid droplets. Habitat is where an organism lives; adaptation is a characteristic or behaviour that helps survival; predator is an animal that hunts others; pollination is transfer of pollen that can enable fertilisation.","marking_guide":"Require the specific correct example, steps and reasoning.","explanation":"The answer must show the taught evidence or method."},{"type":"short_answer","question":"Explain a topic-specific checking method, misconception or improvement.","sample_answer":"I used the phrase ''liquid water changes into water vapour'' to understand evaporation. I checked my definition against the contrasting sentence about vapour cooling to droplets, which describes condensation.","marking_guide":"Require the specific correct example, steps and reasoning.","explanation":"The answer must show the taught evidence or method."}],"parent_notes":"Parent: Check the actual independent response, ask for an explanation and support reading without giving away answers.\n\nParent: **First written model:** Evaporation is liquid changing into vapour; condensation is vapour changing into liquid droplets. Habitat is where an organism lives; adaptation is a characteristic or behaviour that helps survival; predator is an animal that hunts others; pollination is transfer of pollen that can enable fertilisation.\n\nParent: **Second written model:** I used the phrase ''liquid water changes into water vapour'' to understand evaporation. I checked my definition against the contrasting sentence about vapour cooling to droplets, which describes condensation.\n\nParent: Review both written answers and the child''s evidence. The current 90% pass mark requires 8/8 scored MCQs. NESA codes remain unverified.","evidence_instructions":"Keep your word scientist: understand technical vocabulary guided notes, independent task, correction and written responses.","offline_alternative":"Read or print the original text and work through the questions on paper; save work or parent observations.","extension":"Create an original harder word scientist: understand technical vocabulary challenge and explain how you checked it.","stage_hints":{"accept":["Read the Word Scientist: Understand Technical Vocabulary instruction and identify what you need to explain.","Return to the original text or numbers and locate a specific clue connected to word scientist: understand technical vocabulary.","Use the clue or a calculation to justify your own answer, then check and correct a detail."],"teach0":["Read the Recognise a technical term instruction and identify what you need to explain.","Return to the original text or numbers and locate a specific clue connected to recognise a technical term.","Use the clue or a calculation to justify your own answer, then check and correct a detail."],"teach1":["Read the Use context and word parts instruction and identify what you need to explain.","Return to the original text or numbers and locate a specific clue connected to use context and word parts.","Use the clue or a calculation to justify your own answer, then check and correct a detail."],"teach2":["Read the Explain the word accurately instruction and identify what you need to explain.","Return to the original text or numbers and locate a specific clue connected to explain the word accurately.","Use the clue or a calculation to justify your own answer, then check and correct a detail."],"teach3":["Read the Apply and check in a new sentence instruction and identify what you need to explain.","Return to the original text or numbers and locate a specific clue connected to apply and check in a new sentence.","Use the clue or a calculation to justify your own answer, then check and correct a detail."],"learn":["Read the Word Scientist: Understand Technical Vocabulary instruction and identify what you need to explain.","Return to the original text or numbers and locate a specific clue connected to word scientist: understand technical vocabulary.","Use the clue or a calculation to justify your own answer, then check and correct a detail."],"guided":["Read the Word Scientist: Understand Technical Vocabulary instruction and identify what you need to explain.","Return to the original text or numbers and locate a specific clue connected to word scientist: understand technical vocabulary.","Use the clue or a calculation to justify your own answer, then check and correct a detail."],"write":["Read the Word Scientist: Understand Technical Vocabulary instruction and identify what you need to explain.","Return to the original text or numbers and locate a specific clue connected to word scientist: understand technical vocabulary.","Use the clue or a calculation to justify your own answer, then check and correct a detail."],"quiz":["Read the Word Scientist: Understand Technical Vocabulary instruction and identify what you need to explain.","Return to the original text or numbers and locate a specific clue connected to word scientist: understand technical vocabulary.","Use the clue or a calculation to justify your own answer, then check and correct a detail."],"submit":["Read the Word Scientist: Understand Technical Vocabulary instruction and identify what you need to explain.","Return to the original text or numbers and locate a specific clue connected to word scientist: understand technical vocabulary.","Use the clue or a calculation to justify your own answer, then check and correct a detail."]}}'),updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE seed_key='s2-eng-y3-w06-l3';

