UPDATE lessons SET title='Listening Detective: Capture the Important Notes',data=json_patch(data,'{"seed_key":"s2-eng-y3-w06-l4","title":"Listening Detective: Capture the Important Notes","stage":"Stage 2","learning_area":"English","year_level":3,"week":6,"lesson_number":4,"duration_minutes":60,"child_mission":"Investigate listening detective: capture the important notes, learn from complete examples and solve an original mission.","learning_intention":"We are learning to explain and use listening detective: capture the important notes accurately.","success_criteria":["I can explain the topic using an accurate example.","I can follow a worked example and explain the method.","I can practise with feedback before working independently.","I can complete the original challenge.","I can identify and explain one useful correction."],"materials":["Original passages and examples included","Optional paper and pencil or ordinary counters"],"outcome_codes":[],"review_status":"unreviewed","pass":1,"pass_mark":0.9,"coming_soon":null,"source_note":null,"explicit_teaching":null,"resources":null,"sort_activity":null,"word_challenges":null,"suspense_builder":null,"planner_fields":null,"planner_title":null,"planner_intro":null,"spelling":null,"spelling_focus":null,"hoard_words":null,"follow_up_challenges":null,"steps":null,"visual_plan":null,"interactive_activities":[{"type":"flip_cards","title":"Four topic concepts","cards":[{"front":"Listen for the topic and purpose","back":"Before taking notes, decide what you need to learn. A topic sentence often tells the main idea, but not every spoken detail belongs in your notes."},{"front":"Pick key facts instead of every word","back":"Notes can use keywords, arrows, short phrases or labelled drawings. Keep critical relationships; remove repeated filler."},{"front":"Organise notes logically","back":"Group information by subtopic so you can use it later. Use clear abbreviations only if you can remember what they mean."},{"front":"Check accuracy with a second listen or read","back":"Compare notes with the source, add omitted key information and correct guesses. A note that changes the speaker''s meaning is not useful."}]}],"printable_resource":{"title":"Listening Detective: Capture the Important Notes","instructions":"Read the information, complete guided practice and submit your own independent response.","passage":"A fictional guide says: ''Bees visit flowers to collect nectar and pollen. As they move between flowers, pollen may transfer, helping many plants make seeds. Bees need safe habitats and flowering plants.''","prompts":["What information matters?","Which method applies?","What is my independent result?","How can I verify it?"]},"reflection_prompts":null,"reflection_prompt":null,"teach_steps":[{"icon":"🔎","title":"Listen for the topic and purpose","explain":"**Teach:** Before taking notes, decide what you need to learn. A topic sentence often tells the main idea, but not every spoken detail belongs in your notes.\n\n**Look at the original information:** A fictional guide says: ''Bees visit flowers to collect nectar and pollen. As they move between flowers, pollen may transfer, helping many plants make seeds. Bees need safe habitats and flowering plants.''\n\n**Notice:** Which exact part of the information illustrates this principle?","example":"**WATCH MY THINKING:** The guide talks about bees visiting flowers and helping plants. I write the heading Bees and Flowers, not a word-for-word transcript.\n\n**TRY WITH SUPPORT:** **Listen-aloud alternative: read twice.** ''Koalas are marsupials. They eat eucalyptus leaves and spend much of their time resting in trees. Their habitat is threatened in some places by land clearing.'' After the first reading name the topic; after the second write three short notes. **Feedback:** koalas→marsupials; food→eucalyptus leaves; often rest→trees; some habitats threatened→land clearing. Do not write that koalas eat all kinds of leaves.\n\n**CHECK:** Explain a relevant correction, then compare your answer with the model.","notice":"Before taking notes, decide what you need to learn. A topic sentence often tells the main idea, but not every spoken detail belongs in your notes.","check":{"question":"What is the bulletin''s main purpose?","options":["Give garden event information","Tell a dragon story","Explain maths fractions","Advertise a cinema"],"correct_index":0,"explanation":"Give garden event information. The guide talks about bees visiting flowers and helping plants. I write the heading Bees and Flowers, not a word-for-word transcript."},"visual_before":[{"episode":{"title":"A clue about Listening Detective: Capture the Important Notes","transcript":"Pip: The guide spoke so quickly. Should I copy every word?\nJuno: First listen for the topic and important facts. Short notes are easier to use.\nPip: I''ll group what bees do and what bees need.\nJuno: Great. Pause and say one note about how pollen moves between flowers.","scenes":[{"bg":"room","lines":[{"who":"pip","text":"The guide spoke so quickly. Should I copy every word?"},{"who":"juno","text":"First listen for the topic and important facts. Short notes are easier to use."},{"who":"pip","text":"I''ll group what bees do and what bees need."},{"who":"juno","text":"Great. Pause and say one note about how pollen moves between flowers.","pause_after":true}]}]}}]},{"icon":"🧠","title":"Pick key facts instead of every word","explain":"**Teach:** Notes can use keywords, arrows, short phrases or labelled drawings. Keep critical relationships; remove repeated filler.\n\n**Look at the original information:** A fictional guide says: ''Bees visit flowers to collect nectar and pollen. As they move between flowers, pollen may transfer, helping many plants make seeds. Bees need safe habitats and flowering plants.''\n\n**Notice:** Which exact part of the information illustrates this principle?","example":"**WATCH MY THINKING:** My first notes: bees→nectar/pollen; move between flowers→pollen transfer; flowers and habitat→bee needs. I avoid copying every ''and'' or ''the''.\n\n**TRY WITH SUPPORT:** **Listen-aloud alternative: read twice.** ''Koalas are marsupials. They eat eucalyptus leaves and spend much of their time resting in trees. Their habitat is threatened in some places by land clearing.'' After the first reading name the topic; after the second write three short notes. **Feedback:** koalas→marsupials; food→eucalyptus leaves; often rest→trees; some habitats threatened→land clearing. Do not write that koalas eat all kinds of leaves.\n\n**CHECK:** Explain a relevant correction, then compare your answer with the model.","notice":"Notes can use keywords, arrows, short phrases or labelled drawings. Keep critical relationships; remove repeated filler.","check":{"question":"When does the garden open?","options":["8 am","9 am","10 am","11 am"],"correct_index":1,"explanation":"9 am. My first notes: bees→nectar/pollen; move between flowers→pollen transfer; flowers and habitat→bee needs. I avoid copying every ''and'' or ''the''."}},{"icon":"✏️","title":"Organise notes logically","explain":"**Teach:** Group information by subtopic so you can use it later. Use clear abbreviations only if you can remember what they mean.\n\n**Look at the original information:** A fictional guide says: ''Bees visit flowers to collect nectar and pollen. As they move between flowers, pollen may transfer, helping many plants make seeds. Bees need safe habitats and flowering plants.''\n\n**Notice:** Which exact part of the information illustrates this principle?","example":"**WATCH MY THINKING:** I make two headings: What Bees Do and What Bees Need. Pollen transfer belongs in What Bees Do; suitable habitats belong in What Bees Need.\n\n**TRY WITH SUPPORT:** **Listen-aloud alternative: read twice.** ''Koalas are marsupials. They eat eucalyptus leaves and spend much of their time resting in trees. Their habitat is threatened in some places by land clearing.'' After the first reading name the topic; after the second write three short notes. **Feedback:** koalas→marsupials; food→eucalyptus leaves; often rest→trees; some habitats threatened→land clearing. Do not write that koalas eat all kinds of leaves.\n\n**CHECK:** Explain a relevant correction, then compare your answer with the model.","notice":"Group information by subtopic so you can use it later. Use clear abbreviations only if you can remember what they mean.","check":{"question":"When does planting begin?","options":["9 am","10 am","11 am","No time given"],"correct_index":1,"explanation":"10 am. I make two headings: What Bees Do and What Bees Need. Pollen transfer belongs in What Bees Do; suitable habitats belong in What Bees Need."}},{"icon":"✅","title":"Check accuracy with a second listen or read","explain":"**Teach:** Compare notes with the source, add omitted key information and correct guesses. A note that changes the speaker''s meaning is not useful.\n\n**Look at the original information:** A fictional guide says: ''Bees visit flowers to collect nectar and pollen. As they move between flowers, pollen may transfer, helping many plants make seeds. Bees need safe habitats and flowering plants.''\n\n**Notice:** Which exact part of the information illustrates this principle?","example":"**WATCH MY THINKING:** If I wrote ''every plant needs bees'', I correct it. The guide says bees help many plants, not all plants.\n\n**TRY WITH SUPPORT:** **Listen-aloud alternative: read twice.** ''Koalas are marsupials. They eat eucalyptus leaves and spend much of their time resting in trees. Their habitat is threatened in some places by land clearing.'' After the first reading name the topic; after the second write three short notes. **Feedback:** koalas→marsupials; food→eucalyptus leaves; often rest→trees; some habitats threatened→land clearing. Do not write that koalas eat all kinds of leaves.\n\n**CHECK:** Explain a relevant correction, then compare your answer with the model.","notice":"Compare notes with the source, add omitted key information and correct guesses. A note that changes the speaker''s meaning is not useful.","check":{"question":"When is the tool demonstration?","options":["9 am","10 am","11 am","12 pm"],"correct_index":2,"explanation":"11 am. If I wrote ''every plant needs bees'', I correct it. The guide says bees help many plants, not all plants."}}],"worked_example":"## Teacher model\n\nA fictional guide says: ''Bees visit flowers to collect nectar and pollen. As they move between flowers, pollen may transfer, helping many plants make seeds. Bees need safe habitats and flowering plants.''\n\n**1. Listen for the topic and purpose:** The guide talks about bees visiting flowers and helping plants. I write the heading Bees and Flowers, not a word-for-word transcript.\n\n**2. Pick key facts instead of every word:** My first notes: bees→nectar/pollen; move between flowers→pollen transfer; flowers and habitat→bee needs. I avoid copying every ''and'' or ''the''.\n\n**3. Organise notes logically:** I make two headings: What Bees Do and What Bees Need. Pollen transfer belongs in What Bees Do; suitable habitats belong in What Bees Need.\n\n**4. Check accuracy with a second listen or read:** If I wrote ''every plant needs bees'', I correct it. The guide says bees help many plants, not all plants.\n\n**Explain:** What detail matters most in the model?","worked_visuals":[{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 580 180\"><rect width=\"580\" height=\"180\" rx=\"10\" fill=\"#f3f8f5\"/><text x=\"16\" y=\"29\" font-family=\"Arial\" font-size=\"18\" fill=\"#173d2b\">Take accurate notes</text><rect x=\"10\" y=\"58\" width=\"132\" height=\"96\" rx=\"9\" fill=\"#dbeee1\"/><text x=\"20\" y=\"109\" font-family=\"Arial\" font-size=\"15\" fill=\"#244132\">LISTEN</text><rect x=\"154\" y=\"58\" width=\"132\" height=\"96\" rx=\"9\" fill=\"#e3e9f9\"/><text x=\"164\" y=\"109\" font-family=\"Arial\" font-size=\"15\" fill=\"#244132\">KEYWORDS</text><rect x=\"298\" y=\"58\" width=\"132\" height=\"96\" rx=\"9\" fill=\"#dbeee1\"/><text x=\"308\" y=\"109\" font-family=\"Arial\" font-size=\"15\" fill=\"#244132\">GROUP</text><rect x=\"442\" y=\"58\" width=\"132\" height=\"96\" rx=\"9\" fill=\"#e3e9f9\"/><text x=\"452\" y=\"109\" font-family=\"Arial\" font-size=\"15\" fill=\"#244132\">VERIFY</text></svg>","alt":"Four linked steps for Listening Detective: Capture the Important Notes: LISTEN, KEYWORDS, GROUP, VERIFY.","caption":"Use the steps to organise and check your answer."}],"guided_practice":"**Listen-aloud alternative: read twice.** ''Koalas are marsupials. They eat eucalyptus leaves and spend much of their time resting in trees. Their habitat is threatened in some places by land clearing.'' After the first reading name the topic; after the second write three short notes. **Feedback:** koalas→marsupials; food→eucalyptus leaves; often rest→trees; some habitats threatened→land clearing. Do not write that koalas eat all kinds of leaves.","independent_task":"**Hear and note a weather bulletin.** Ask an adult to read this text once, then again, or read it twice yourself: ''The community garden will open at nine on Saturday. Volunteers should bring closed shoes, a hat and drinking water. A planting activity begins at ten, while the tool demonstration starts at eleven. If heavy rain develops, organisers will postpone outdoor work.'' Make a titled notes sheet listing start time, three things to bring, two activity times and the weather condition. Then write a two-sentence spoken or written summary from your notes. Check against the bulletin and mark one correction or confirm accuracy.","response_prompt":"Complete the original listening detective: capture the important notes task, including evidence or working and one correction.","quiz":[{"type":"multiple_choice","question":"What is the bulletin''s main purpose?","options":["Give garden event information","Tell a dragon story","Explain maths fractions","Advertise a cinema"],"correct_index":0,"explanation":"Give garden event information. Compare this with the relevant taught example."},{"type":"multiple_choice","question":"When does the garden open?","options":["8 am","9 am","10 am","11 am"],"correct_index":1,"explanation":"9 am. Compare this with the relevant taught example."},{"type":"multiple_choice","question":"When does planting begin?","options":["9 am","10 am","11 am","No time given"],"correct_index":1,"explanation":"10 am. Compare this with the relevant taught example."},{"type":"multiple_choice","question":"When is the tool demonstration?","options":["9 am","10 am","11 am","12 pm"],"correct_index":2,"explanation":"11 am. Compare this with the relevant taught example."},{"type":"multiple_choice","question":"Which item is requested?","options":["Closed shoes","Swimming goggles","A musical instrument","A bicycle helmet"],"correct_index":0,"explanation":"Closed shoes. Compare this with the relevant taught example."},{"type":"multiple_choice","question":"Which drink should volunteers bring?","options":["Drinking water","Only fizzy drinks","None","A hot coffee"],"correct_index":0,"explanation":"Drinking water. Compare this with the relevant taught example."},{"type":"multiple_choice","question":"What happens if heavy rain develops?","options":["Outdoor work is postponed","Planting moves to midnight","The event becomes a race","Everyone must keep digging"],"correct_index":0,"explanation":"Outdoor work is postponed. Compare this with the relevant taught example."},{"type":"multiple_choice","question":"Which is the strongest note?","options":["Tools→11 am","It is definitely Tuesday","A dragon arrives","All children must plant"],"correct_index":0,"explanation":"Tools→11 am. Compare this with the relevant taught example."},{"type":"short_answer","question":"Complete the independent listening detective: capture the important notes challenge.","sample_answer":"Community Garden Saturday: open 9 am; bring closed shoes, hat and drinking water; planting 10 am; tool demonstration 11 am; heavy rain→outdoor work postponed.","marking_guide":"Require the specific correct example, steps and reasoning.","explanation":"The answer must show the taught evidence or method."},{"type":"short_answer","question":"Explain a topic-specific checking method, misconception or improvement.","sample_answer":"The garden opens at nine on Saturday, with planting at ten and a tool demonstration at eleven. Volunteers should wear closed shoes and a hat, bring water, and expect outdoor work to be postponed if heavy rain occurs.","marking_guide":"Require the specific correct example, steps and reasoning.","explanation":"The answer must show the taught evidence or method."}],"parent_notes":"Parent: Check the actual independent response, ask for an explanation and support reading without giving away answers.\n\nParent: **First written model:** Community Garden Saturday: open 9 am; bring closed shoes, hat and drinking water; planting 10 am; tool demonstration 11 am; heavy rain→outdoor work postponed.\n\nParent: **Second written model:** The garden opens at nine on Saturday, with planting at ten and a tool demonstration at eleven. Volunteers should wear closed shoes and a hat, bring water, and expect outdoor work to be postponed if heavy rain occurs.\n\nParent: Review both written answers and the child''s evidence. The current 90% pass mark requires 8/8 scored MCQs. NESA codes remain unverified.","evidence_instructions":"Keep your listening detective: capture the important notes guided notes, independent task, correction and written responses.","offline_alternative":"Read or print the original text and work through the questions on paper; save work or parent observations.","extension":"Create an original harder listening detective: capture the important notes challenge and explain how you checked it.","stage_hints":{"accept":["Read the Listening Detective: Capture the Important Notes instruction and identify what you need to explain.","Return to the original text or numbers and locate a specific clue connected to listening detective: capture the important notes.","Use the clue or a calculation to justify your own answer, then check and correct a detail."],"teach0":["Read the Listen for the topic and purpose instruction and identify what you need to explain.","Return to the original text or numbers and locate a specific clue connected to listen for the topic and purpose.","Use the clue or a calculation to justify your own answer, then check and correct a detail."],"teach1":["Read the Pick key facts instead of every word instruction and identify what you need to explain.","Return to the original text or numbers and locate a specific clue connected to pick key facts instead of every word.","Use the clue or a calculation to justify your own answer, then check and correct a detail."],"teach2":["Read the Organise notes logically instruction and identify what you need to explain.","Return to the original text or numbers and locate a specific clue connected to organise notes logically.","Use the clue or a calculation to justify your own answer, then check and correct a detail."],"teach3":["Read the Check accuracy with a second listen or read instruction and identify what you need to explain.","Return to the original text or numbers and locate a specific clue connected to check accuracy with a second listen or read.","Use the clue or a calculation to justify your own answer, then check and correct a detail."],"learn":["Read the Listening Detective: Capture the Important Notes instruction and identify what you need to explain.","Return to the original text or numbers and locate a specific clue connected to listening detective: capture the important notes.","Use the clue or a calculation to justify your own answer, then check and correct a detail."],"guided":["Read the Listening Detective: Capture the Important Notes instruction and identify what you need to explain.","Return to the original text or nu