UPDATE lessons SET title='Subtraction Fact Families: Undo Addition',data=json_patch(data,'{"seed_key":"s2-mat-y3-w06-l1","title":"Subtraction Fact Families: Undo Addition","stage":"Stage 2","learning_area":"Mathematics","year_level":3,"week":6,"lesson_number":1,"duration_minutes":60,"child_mission":"Investigate subtraction fact families: undo addition, learn from complete examples and solve an original mission.","learning_intention":"We are learning to explain and use subtraction fact families: undo addition accurately.","success_criteria":["I can explain the topic using an accurate example.","I can follow a worked example and explain the method.","I can practise with feedback before working independently.","I can complete the original challenge.","I can identify and explain one useful correction."],"materials":["Original passages and examples included","Optional paper and pencil or ordinary counters"],"outcome_codes":[],"review_status":"unreviewed","pass":1,"pass_mark":0.9,"coming_soon":null,"source_note":null,"explicit_teaching":null,"resources":null,"sort_activity":null,"word_challenges":null,"suspense_builder":null,"planner_fields":null,"planner_title":null,"planner_intro":null,"spelling":null,"spelling_focus":null,"hoard_words":null,"follow_up_challenges":null,"steps":null,"visual_plan":null,"interactive_activities":[{"type":"flip_cards","title":"Four topic concepts","cards":[{"front":"See the whole and its parts","back":"Addition puts parts together; subtraction can find what remains or a missing part. Both operations describe the same three numbers."},{"front":"Use subtraction to find a missing part","back":"If the whole is known, subtract one part to find the other. The answer must fit the original total."},{"front":"Build a four-equation fact family","back":"A fact family often contains two addition facts and two subtraction facts made from the same three numbers."},{"front":"Solve a word problem and check","back":"Decide which amount is the whole and which amount is known. Label the answer, then verify with the inverse operation."}]}],"printable_resource":{"title":"Subtraction Fact Families: Undo Addition","instructions":"Read the information, complete guided practice and submit your own independent response.","passage":"A box contains 17 craft beads. Ten are blue and seven are yellow.","prompts":["What information matters?","Which method applies?","What is my independent result?","How can I verify it?"]},"reflection_prompts":null,"reflection_prompt":null,"teach_steps":[{"icon":"🔎","title":"See the whole and its parts","explain":"**Teach:** Addition puts parts together; subtraction can find what remains or a missing part. Both operations describe the same three numbers.\n\n**Look at the original information:** A box contains 17 craft beads. Ten are blue and seven are yellow.\n\n**Notice:** Which exact part of the information illustrates this principle?","example":"**WATCH MY THINKING:** 10+7=17. The whole is 17; its two parts are 10 and 7.\n\n**TRY WITH SUPPORT:** Find missing parts: 18−11=7, checked by 11+7=18; 20−8=12, checked by 12+8=20. Create the fact family for 5,9,14: 5+9=14, 9+5=14, 14−5=9, 14−9=5. **Try:** 26−7=19; check 19+7=26. **Spot the error:** 17−10=8 is wrong because 10+8=18, not 17.\n\n**CHECK:** Explain a relevant correction, then compare your answer with the model.","notice":"Addition puts parts together; subtraction can find what remains or a missing part. Both operations describe the same three numbers.","check":{"question":"17−10=?","options":["6","7","8","9"],"correct_index":1,"explanation":"7. 10+7=17. The whole is 17; its two parts are 10 and 7."},"visual_before":[{"episode":{"title":"A clue about Subtraction Fact Families: Undo Addition","transcript":"Pip: Seventeen beads altogether: ten blue and seven yellow.\nJuno: Add the parts to check the whole, then try subtraction to find a missing part.\nPip: Seventeen minus ten is seven, and ten plus seven restores seventeen.\nJuno: Exactly. Pause and build the related facts using six, eight and fourteen.","scenes":[{"bg":"room","lines":[{"who":"pip","text":"Seventeen beads altogether: ten blue and seven yellow."},{"who":"juno","text":"Add the parts to check the whole, then try subtraction to find a missing part."},{"who":"pip","text":"Seventeen minus ten is seven, and ten plus seven restores seventeen."},{"who":"juno","text":"Exactly. Pause and build the related facts using six, eight and fourteen.","pause_after":true}]}]}}]},{"icon":"🧠","title":"Use subtraction to find a missing part","explain":"**Teach:** If the whole is known, subtract one part to find the other. The answer must fit the original total.\n\n**Look at the original information:** A box contains 17 craft beads. Ten are blue and seven are yellow.\n\n**Notice:** Which exact part of the information illustrates this principle?","example":"**WATCH MY THINKING:** 17−10=7. I check with 10+7=17; subtracting seven instead would leave ten.\n\n**TRY WITH SUPPORT:** Find missing parts: 18−11=7, checked by 11+7=18; 20−8=12, checked by 12+8=20. Create the fact family for 5,9,14: 5+9=14, 9+5=14, 14−5=9, 14−9=5. **Try:** 26−7=19; check 19+7=26. **Spot the error:** 17−10=8 is wrong because 10+8=18, not 17.\n\n**CHECK:** Explain a relevant correction, then compare your answer with the model.","notice":"If the whole is known, subtract one part to find the other. The answer must fit the original total.","check":{"question":"10+7=?","options":["16","17","18","19"],"correct_index":1,"explanation":"17. 17−10=7. I check with 10+7=17; subtracting seven instead would leave ten."}},{"icon":"✏️","title":"Build a four-equation fact family","explain":"**Teach:** A fact family often contains two addition facts and two subtraction facts made from the same three numbers.\n\n**Look at the original information:** A box contains 17 craft beads. Ten are blue and seven are yellow.\n\n**Notice:** Which exact part of the information illustrates this principle?","example":"**WATCH MY THINKING:** 6+8=14; 8+6=14; 14−6=8; 14−8=6. The order swaps but the relationship does not.\n\n**TRY WITH SUPPORT:** Find missing parts: 18−11=7, checked by 11+7=18; 20−8=12, checked by 12+8=20. Create the fact family for 5,9,14: 5+9=14, 9+5=14, 14−5=9, 14−9=5. **Try:** 26−7=19; check 19+7=26. **Spot the error:** 17−10=8 is wrong because 10+8=18, not 17.\n\n**CHECK:** Explain a relevant correction, then compare your answer with the model.","notice":"A fact family often contains two addition facts and two subtraction facts made from the same three numbers.","check":{"question":"14−6=?","options":["6","7","8","9"],"correct_index":2,"explanation":"8. 6+8=14; 8+6=14; 14−6=8; 14−8=6. The order swaps but the relationship does not."}},{"icon":"✅","title":"Solve a word problem and check","explain":"**Teach:** Decide which amount is the whole and which amount is known. Label the answer, then verify with the inverse operation.\n\n**Look at the original information:** A box contains 17 craft beads. Ten are blue and seven are yellow.\n\n**Notice:** Which exact part of the information illustrates this principle?","example":"**WATCH MY THINKING:** A tray had 23 biscuits, and 9 were eaten. 23−9=14 remain; 14+9=23 checks the answer.\n\n**TRY WITH SUPPORT:** Find missing parts: 18−11=7, checked by 11+7=18; 20−8=12, checked by 12+8=20. Create the fact family for 5,9,14: 5+9=14, 9+5=14, 14−5=9, 14−9=5. **Try:** 26−7=19; check 19+7=26. **Spot the error:** 17−10=8 is wrong because 10+8=18, not 17.\n\n**CHECK:** Explain a relevant correction, then compare your answer with the model.","notice":"Decide which amount is the whole and which amount is known. Label the answer, then verify with the inverse operation.","check":{"question":"Which checks 23−9=14?","options":["14+9=23","14−9=23","23+9=14","9−14=23"],"correct_index":0,"explanation":"14+9=23. A tray had 23 biscuits, and 9 were eaten. 23−9=14 remain; 14+9=23 checks the answer."}}],"worked_example":"## Teacher model\n\nA box contains 17 craft beads. Ten are blue and seven are yellow.\n\n**1. See the whole and its parts:** 10+7=17. The whole is 17; its two parts are 10 and 7.\n\n**2. Use subtraction to find a missing part:** 17−10=7. I check with 10+7=17; subtracting seven instead would leave ten.\n\n**3. Build a four-equation fact family:** 6+8=14; 8+6=14; 14−6=8; 14−8=6. The order swaps but the relationship does not.\n\n**4. Solve a word problem and check:** A tray had 23 biscuits, and 9 were eaten. 23−9=14 remain; 14+9=23 checks the answer.\n\n**Explain:** What detail matters most in the model?","worked_visuals":[{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 580 180\"><rect width=\"580\" height=\"180\" rx=\"10\" fill=\"#f3f8f5\"/><text x=\"16\" y=\"29\" font-family=\"Arial\" font-size=\"18\" fill=\"#173d2b\">Build a fact family</text><rect x=\"10\" y=\"58\" width=\"132\" height=\"96\" rx=\"9\" fill=\"#dbeee1\"/><text x=\"20\" y=\"109\" font-family=\"Arial\" font-size=\"15\" fill=\"#244132\">WHOLE</text><rect x=\"154\" y=\"58\" width=\"132\" height=\"96\" rx=\"9\" fill=\"#e3e9f9\"/><text x=\"164\" y=\"109\" font-family=\"Arial\" font-size=\"15\" fill=\"#244132\">PARTS</text><rect x=\"298\" y=\"58\" width=\"132\" height=\"96\" rx=\"9\" fill=\"#dbeee1\"/><text x=\"308\" y=\"109\" font-family=\"Arial\" font-size=\"15\" fill=\"#244132\">SUBTRACT</text><rect x=\"442\" y=\"58\" width=\"132\" height=\"96\" rx=\"9\" fill=\"#e3e9f9\"/><text x=\"452\" y=\"109\" font-family=\"Arial\" font-size=\"15\" fill=\"#244132\">CHECK</text></svg>","alt":"Four linked steps for Subtraction Fact Families: Undo Addition: WHOLE, PARTS, SUBTRACT, CHECK.","caption":"Use the steps to organise and check your answer."}],"guided_practice":"Find missing parts: 18−11=7, checked by 11+7=18; 20−8=12, checked by 12+8=20. Create the fact family for 5,9,14: 5+9=14, 9+5=14, 14−5=9, 14−9=5. **Try:** 26−7=19; check 19+7=26. **Spot the error:** 17−10=8 is wrong because 10+8=18, not 17.","independent_task":"**Craft shop fact-family challenge:** A shop has 32 beads, 18 red and the rest green. Find the green beads and write all four related fact-family equations. Then 45 pencils are delivered and 27 are used; find the remainder and check by addition. Invent your own three-number family with a whole between 25 and 50. Explain one subtraction mistake the inverse check would catch.","response_prompt":"Complete the original subtraction fact families: undo addition task, including evidence or working and one correction.","quiz":[{"type":"multiple_choice","question":"17−10=?","options":["6","7","8","9"],"correct_index":1,"explanation":"7. Compare this with the relevant taught example."},{"type":"multiple_choice","question":"10+7=?","options":["16","17","18","19"],"correct_index":1,"explanation":"17. Compare this with the relevant taught example."},{"type":"multiple_choice","question":"14−6=?","options":["6","7","8","9"],"correct_index":2,"explanation":"8. Compare this with the relevant taught example."},{"type":"multiple_choice","question":"Which checks 23−9=14?","options":["14+9=23","14−9=23","23+9=14","9−14=23"],"correct_index":0,"explanation":"14+9=23. Compare this with the relevant taught example."},{"type":"multiple_choice","question":"32−18=?","options":["12","13","14","15"],"correct_index":2,"explanation":"14. Compare this with the relevant taught example."},{"type":"multiple_choice","question":"Which is in the 18,14,32 fact family?","options":["32−14=18","32+14=18","18−14=32","32−18=15"],"correct_index":0,"explanation":"32−14=18. Compare this with the relevant taught example."},{"type":"multiple_choice","question":"45−27=?","options":["16","17","18","19"],"correct_index":2,"explanation":"18. Compare this with the relevant taught example."},{"type":"multiple_choice","question":"What is a correct inverse check of 45−27=18?","options":["18+27=45","18−27=45","45+27=18","27−45=18"],"correct_index":0,"explanation":"18+27=45. Compare this with the relevant taught example."},{"type":"short_answer","question":"Complete the independent subtraction fact families: undo addition challenge.","sample_answer":"32−18=14 green beads. Four facts: 18+14=32; 14+18=32; 32−18=14; 32−14=18. 45−27=18 pencils remain, and 18+27=45.","marking_guide":"Require the specific correct example, steps and reasoning.","explanation":"The answer must show the taught evidence or method."},{"type":"short_answer","question":"Explain a topic-specific checking method, misconception or improvement.","sample_answer":"A possible new family is 16,19,35: 16+19=35, 19+16=35, 35−16=19, 35−19=16. If I mistakenly say 32−18=15, the check 18+15=33 shows that I have one too many.","marking_guide":"Require the specific correct example, steps and reasoning.","explanation":"The answer must show the taught evidence or method."}],"parent_notes":"Parent: Check the actual independent response, ask for an explanation and support reading without giving away answers.\n\nParent: **First written model:** 32−18=14 green beads. Four facts: 18+14=32; 14+18=32; 32−18=14; 32−14=18. 45−27=18 pencils remain, and 18+27=45.\n\nParent: **Second written model:** A possible new family is 16,19,35: 16+19=35, 19+16=35, 35−16=19, 35−19=16. If I mistakenly say 32−18=15, the check 18+15=33 shows that I have one too many.\n\nParent: Review both written answers and the child''s evidence. The current 90% pass mark requires 8/8 scored MCQs. NESA codes remain unverified.","evidence_instructions":"Keep your subtraction fact families: undo addition guided notes, independent task, correction and written responses.","offline_alternative":"Read or print the original text and work through the questions on paper; save work or parent observations.","extension":"Create an original harder subtraction fact families: undo addition challenge and explain how you checked it.","stage_hints":{"accept":["Read the Subtraction Fact Families: Undo Addition instruction and identify what you need to explain.","Return to the original text or numbers and loc